<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { Plus, Search, PriceTag } from '@element-plus/icons-vue'
import { api, query } from '../api'
import { useApp } from '../store'
import { today } from '../utils'
import DataTable from '../components/DataTable.vue'
const app = useApp(), rows = ref<any[]>([]), products = ref<any[]>([]), customers = ref<any[]>([]), search = ref(''), busy = ref(false), saving = ref(false), open = ref(false), quoteOpen = ref(false)
const form = reactive<any>({}), quoteForm = reactive<any>({ product_id: undefined, customer_id: undefined, quantity: '1', date: today(), channel: 'wholesale' }), quote = ref<any>(null)
const typeLabels: Record<string,string> = { customer: '客户专属价', level: '客户等级价', quantity: '数量阶梯价', promotion: '限时促销价' }
const levels = computed(() => [...new Set(['普通客户','银牌客户','金牌客户','VIP客户',...customers.value.map(c => c.data.level).filter(Boolean)])])
async function load() { busy.value = true; try { rows.value = (await api('/prices')).items.map((r:any) => ({ ...r, kind_name: typeLabels[r.kind], period: (r.start_date || '不限') + ' 至 ' + (r.end_date || '不限') })) } catch {} finally { busy.value = false } }
watch(() => app.tick, load); onMounted(async () => { load(); try { [products.value, customers.value] = await Promise.all(['product','customer'].map(async k => (await api('/masters/' + k + '?active=true')).items)) } catch {} })
const filtered = computed(() => rows.value.filter(r => !search.value || JSON.stringify(r).includes(search.value)))
const columns = computed(() => [{ key:'name',label:'规则名称',minWidth:160 },{key:'kind_name',label:'规则类型',minWidth:120},{key:'product_name',label:'适用商品',minWidth:160},{key:'customer_name',label:'指定客户',minWidth:130},{key:'customer_level',label:'客户等级'},{key:'min_quantity',label:'起订数量',type:'qty'},{key:'price',label:'规则单价',type:'money',hidden:!app.amountVisible},{key:'period',label:'生效期间',minWidth:210},{key:'active',label:'状态',type:'boolean',width:85}])
function edit(row?:any) { Object.assign(form, row ? JSON.parse(JSON.stringify(row)) : {id:0,name:'',kind:'customer',product_id:undefined,customer_id:undefined,customer_level:'普通客户',min_quantity:'0',max_quantity:'0',price:'',min_price:'0',start_date:'',end_date:'',priority:0,active:true}); open.value = true }
async function save() { saving.value = true; try { await api('/prices' + (form.id ? '/' + form.id : ''), form.id ? 'PUT' : 'POST', { ...form, start_date:form.start_date || '',end_date:form.end_date || '' }); ElMessage.success('价格规则已保存'); open.value = false; app.changed() } catch {} finally { saving.value = false } }
async function calculate() { saving.value = true; try { quote.value = await api('/prices/quote?' + query(quoteForm)) } catch {} finally { saving.value = false } }
</script>
<template>
  <div class="page-head"><div><h1>价格管理</h1><p>客户专属价、等级价、阶梯价与促销价，由统一规则计算最终售价。</p></div><div class="page-actions"><el-button :icon="PriceTag" @click="quoteOpen = true; quote = null">试算销售价格</el-button><el-button v-if="app.can('price.edit')" type="primary" :icon="Plus" :disabled="!app.writable('price')" @click="edit()">新增价格规则</el-button></div></div>
  <div class="hint-box mb24">匹配顺序：客户专属价 → 客户等级价 → 限时促销价 → 数量阶梯价 → 商品销售价 → 指导价。同类规则按优先级、起订数量匹配；未命中规则时可应用客户基础价折扣。</div>
  <section class="panel"><div class="filter-row"><el-input v-model="search" :prefix-icon="Search" placeholder="搜索规则、商品或客户" clearable/><div class="spacer"></div><span class="muted">{{ filtered.length }} 条定价规则</span></div><DataTable :rows="filtered" :columns="columns" :loading="busy" empty="暂无价格规则，默认使用商品销售价"><template #actions="{ row }"><el-button link type="primary" @click="edit(row)">{{ app.can('price.edit') ? '编辑规则' : '查看规则' }}</el-button></template></DataTable></section>
  <el-drawer v-model="open" :title="form.id ? '编辑价格规则' : '新增价格规则'" size="650px"><el-form label-position="top" :disabled="!app.can('price.edit') || !app.writable('price')"><div class="form-grid two"><el-form-item class="wide" label="规则名称 *"><el-input v-model="form.name" placeholder="例如：金牌客户专享价"/></el-form-item><el-form-item label="规则类型"><el-select v-model="form.kind"><el-option v-for="(label,key) in typeLabels" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="适用商品 *"><el-select v-model="form.product_id" filterable><el-option v-for="p in products" :key="p.id" :label="p.code+' · '+p.name" :value="p.id"/></el-select></el-form-item><el-form-item v-if="form.kind === 'customer'" label="指定客户 *"><el-select v-model="form.customer_id" filterable><el-option v-for="c in customers" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item v-if="form.kind === 'level'" label="客户等级 *"><el-select v-model="form.customer_level" filterable allow-create default-first-option><el-option v-for="level in levels" :key="level" :label="level" :value="level"/></el-select></el-form-item><el-form-item label="规则单价 *"><el-input v-model="form.price" inputmode="decimal"><template #prefix>¥</template></el-input></el-form-item><el-form-item label="最低售价"><el-input v-model="form.min_price" inputmode="decimal"><template #prefix>¥</template></el-input></el-form-item><el-form-item label="起订数量"><el-input v-model="form.min_quantity" inputmode="decimal"/></el-form-item><el-form-item label="最大数量（0 不限）"><el-input v-model="form.max_quantity" inputmode="decimal"/></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="form.start_date" type="date" value-format="YYYY-MM-DD" placeholder="不限"/></el-form-item><el-form-item label="失效日期"><el-date-picker v-model="form.end_date" type="date" value-format="YYYY-MM-DD" placeholder="不限"/></el-form-item><el-form-item label="同类规则优先级（越大越优先）"><el-input-number v-model="form.priority" :precision="0" controls-position="right"/></el-form-item><el-form-item label="规则状态"><el-switch v-model="form.active" active-text="启用" inactive-text="停用"/></el-form-item></div></el-form><template #footer><el-button @click="open = false">取消</el-button><el-button v-if="app.can('price.edit')" type="primary" :disabled="!app.writable('price')" :loading="saving" @click="save">保存规则</el-button></template></el-drawer>
  <el-dialog v-model="quoteOpen" title="销售价格试算" width="590px"><el-form label-position="top"><el-form-item label="商品"><el-select v-model="quoteForm.product_id" filterable><el-option v-for="p in products" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><div class="form-grid two"><el-form-item label="客户"><el-select v-model="quoteForm.customer_id" filterable clearable><el-option v-for="c in customers" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="数量"><el-input v-model="quoteForm.quantity" inputmode="decimal"/></el-form-item><el-form-item label="业务日期"><el-date-picker v-model="quoteForm.date" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="销售渠道"><el-select v-model="quoteForm.channel"><el-option label="批发" value="wholesale"/><el-option label="零售" value="retail"/></el-select></el-form-item></div></el-form><div v-if="quote" class="summary-strip"><div><label>匹配规则</label><strong style="font-size:14px">{{ quote.source }}</strong></div><div><label>最终单价</label><strong>¥ {{ quote.price ?? '—' }}</strong></div><div><label>最低售价</label><strong>¥ {{ quote.min_price ?? '—' }}</strong></div></div><template #footer><el-button @click="quoteOpen = false">关闭</el-button><el-button type="primary" :loading="saving" @click="calculate">计算价格</el-button></template></el-dialog>
</template>
